(* [comment removed for export] *)
Definition KP (a : Z) : Prop := ~ (sp - SS <= a < sp) /\ ~ (P + 160 <= a < P + 184) /\ ~ (P + 200 <= a < P + 209) /\ ~ (P + 256 <= a < P + 264).

(* [comment removed for export] *)
Lemma sinv_upd : forall M M' model cr ps st' stk' sfx q q' e,
  sinv M model cr ps -> TK.samem KP M M' -> mem_grows M M' -> PML.ps_win ps = Some (q, e) -> q <= q' <= e ->
  PML.u64 M' (P + 200) q' -> PML.u8 M' (P + 208) st' -> PML.u64 M' (P + 256) (PML.ps_sb ps + Z.of_nat (length stk')) -> PML.ps_stack ps = stk' ++ sfx ->
  PML.wf_ps (PSB.ps_upd ps st' (PML.ps_more ps) stk' (Some (q', e))) -> PML.ws_ok (PSB.ps_upd ps st' (PML.ps_more ps) stk' (Some (q', e))) ->
  PML.buf_bound (PSB.ps_upd ps st' (PML.ps_more ps) stk' (Some (q', e))) B ->
  sinv M' model cr (PSB.ps_upd ps st' (PML.ps_more ps) stk' (Some (q', e))).
